data.code:
-- 1. Make an existing file bigger
ALTER DATABASE DATAFILE '/u01/oradata/ORCL/demo_ts01.dbf'
  RESIZE 300M;

-- 2. Let the file grow on its own, with a ceiling
ALTER DATABASE DATAFILE '/u01/oradata/ORCL/demo_ts01.dbf'
  AUTOEXTEND ON NEXT 50M MAXSIZE 2G;

-- 3. Add another file to the tablespace
ALTER TABLESPACE demo_ts
  ADD DATAFILE '/u01/oradata/ORCL/demo_ts02.dbf' SIZE 500M
  AUTOEXTEND ON NEXT 50M MAXSIZE 2G;

